"""Worker subproblem: build, solve and certify one immutable proposal.

The worker minimises

    f = 0.5*sum x**2 + 0.5*rho*sum_{live e}(L[e]/c[e]-B[e])**2 - (R if admit)

over nonnegative slot amounts with one (in)equality per owned commodity.
The reported proposal carries the amounts, the recomputed edge loads and the
per-commodity potentials, chosen so that the tangent certificate in the
protocol holds exactly at the reported numbers.
"""
import numpy as np

from .qp import solve_qp


def tol(a, b):
    return 1e-7 + 1e-7 * max(abs(a), abs(b))


def available_slots(paths_k, caps):
    """Slot indices whose path is non-null and uses only live edges."""
    out = []
    for p, path in enumerate(paths_k):
        if path is None:
            continue
        ok = True
        for e in path:
            if caps[e] <= 0.0:
                ok = False
                break
        if ok:
            out.append(p)
    return out


class _Context:
    def __init__(self, owned, paths, caps, demand, mode, rho, B):
        self.owned = list(owned)
        self.paths = paths
        self.caps = np.asarray(caps, dtype=float)
        self.demand = np.asarray(demand, dtype=float)
        self.mode = mode
        self.rho = float(rho)
        self.B = np.asarray(B, dtype=float)
        self.E = len(self.caps)
        self.live = [e for e in range(self.E) if self.caps[e] > 0.0]
        self.avail = {k: available_slots(paths[k], self.caps) for k in self.owned}
        self.var = []
        for k in self.owned:
            if self.demand[k] <= 0.0:
                continue
            for p in self.avail[k]:
                self.var.append((k, p))
        self.slot_of = {kp: j for j, kp in enumerate(self.var)}
        self.rows = [k for k in self.owned
                     if self.demand[k] > 0.0 and self.avail[k]]

    def route_load(self, xval):
        L = np.zeros(self.E)
        for (k, p), j in self.slot_of.items():
            v = xval[j]
            if v != 0.0:
                for e in self.paths[k][p]:
                    L[e] += v
        return L

    def derivative(self, xval, resid):
        """G for every available positive-demand slot."""
        r = self.rho
        G = {}
        for (k, p), j in self.slot_of.items():
            v = xval[j]
            g = v
            for e in self.paths[k][p]:
                g += r * resid[e] / self.caps[e]
            if self.mode == "admit":
                g -= 1.0
            G[(k, p)] = g
        return G

    def evaluate(self, x):
        """Full evaluation of a candidate primal point."""
        xval = np.asarray(x, dtype=float)
        L = self.route_load(xval)
        resid = np.zeros(self.E)
        for e in self.live:
            resid[e] = L[e] / self.caps[e] - self.B[e]
        G = self.derivative(xval, resid)
        f = 0.0
        for v in xval:
            f += 0.5 * float(v) ** 2
        for e in self.live:
            f += 0.5 * self.rho * resid[e] ** 2
        if self.mode == "admit":
            f -= float(xval.sum())
        lam = {}
        for k in self.owned:
            if self.demand[k] <= 0.0:
                lam[k] = 0.0
                continue
            mx = None
            for p in self.avail[k]:
                if xval[self.slot_of[(k, p)]] > 0.0:
                    g = G[(k, p)]
                    if mx is None or g > mx:
                        mx = g
            val = -mx if mx is not None else 0.0
            if self.mode == "admit" and val < 0.0:
                val = 0.0
            lam[k] = val
        D = f
        for (k, p), j in self.slot_of.items():
            v = float(xval[j])
            if v != 0.0:
                D -= v * G[(k, p)]
        for k in self.rows:
            D -= self.demand[k] * lam[k]
        return {
            "x": xval, "L": L, "resid": resid, "G": G, "lam": lam, "f": f, "D": D,
        }

    def violation(self, ev):
        worst = 0.0
        xval = ev["x"]
        demand = self.demand
        if len(xval) and xval.min() < 0.0:
            worst = max(worst, float(-xval.min()) / max(1.0, float(np.abs(xval).max())))
        sums = {}
        for (k, p), j in self.slot_of.items():
            sums[k] = sums.get(k, 0.0) + float(xval[j])
        for k in self.rows:
            s = sums.get(k, 0.0)
            d = float(demand[k])
            if self.mode == "route":
                worst = max(worst, abs(s - d) / max(1.0, abs(d)))
            else:
                worst = max(worst, max(0.0, s - d) / max(1.0, abs(d)))
        for (k, p), g in ev["G"].items():
            val = g + ev["lam"][k]
            if val < -tol(val, 0.0):
                worst = max(worst, float(-val) / max(1.0, abs(val)))
        fd = abs(ev["f"] - ev["D"])
        if fd > tol(ev["f"], ev["D"]):
            worst = max(worst, fd / max(1.0, abs(ev["f"]), abs(ev["D"])))
        return worst


def _initial_points(ctx, Q, q, C, d, eq):
    starts = []
    if ctx.mode == "route":
        s = np.zeros(len(ctx.var))
        for i, k in enumerate(ctx.rows):
            v = d[i] / len(ctx.avail[k])
            for p in ctx.avail[k]:
                s[ctx.slot_of[(k, p)]] = v
        starts.append(s)
        s2 = np.zeros(len(ctx.var))
        for i, k in enumerate(ctx.rows):
            s2[ctx.slot_of[(k, ctx.avail[k][0])]] = d[i]
        starts.append(s2)
    else:
        starts.append(np.zeros(len(ctx.var)))
        s = np.zeros(len(ctx.var))
        for i, k in enumerate(ctx.rows):
            v = min(d[i] / len(ctx.avail[k]), 1.0)
            for p in ctx.avail[k]:
                s[ctx.slot_of[(k, p)]] = v
        starts.append(s)
    return starts


def solve_worker(owned, paths, caps, demand, mode, rho, B):
    """Return the proposal dictionary for one captured worker problem."""
    ctx = _Context(owned, paths, caps, demand, mode, rho, B)
    if mode == "route":
        unroutable = [k for k in ctx.owned
                      if ctx.demand[k] > 0.0 and not ctx.avail[k]]
        if unroutable:
            return {"status": "infeasible",
                    "unroutable": [int(k) for k in unroutable]}

    n = len(ctx.var)
    if n == 0:
        ev = ctx.evaluate(np.zeros(0))
        return _proposal(ctx, ev)

    live = ctx.live
    A = np.zeros((len(live), n))
    row_of = {e: i for i, e in enumerate(live)}
    for (k, p), j in ctx.slot_of.items():
        for e in ctx.paths[k][p]:
            A[row_of[e], j] = 1.0 / ctx.caps[e]
    Bl = np.array([ctx.B[e] for e in live], dtype=float)
    Q = np.eye(n) + ctx.rho * (A.T @ A)
    q = -ctx.rho * (A.T @ Bl)
    if mode == "admit":
        q = q - 1.0
    m = len(ctx.rows)
    C = np.zeros((m, n))
    d = np.zeros(m)
    eq = [mode == "route"] * m
    for i, k in enumerate(ctx.rows):
        for p in ctx.avail[k]:
            C[i, ctx.slot_of[(k, p)]] = 1.0
        d[i] = float(ctx.demand[k])

    best = None
    for x0 in _initial_points(ctx, Q, q, C, d, eq):
        xs, ls, ok = solve_qp(Q, q, C, d, eq, x0)
        xs = np.maximum(np.asarray(xs, dtype=float), 0.0)
        ev = ctx.evaluate(xs)
        score = ctx.violation(ev)
        if best is None or score < best[0]:
            best = (score, ev)
        if score <= 0.0:
            break
    ev = best[1]

    # snap near-zero entries to exactly zero, then re-evaluate
    snap = np.array(ev["x"], dtype=float)
    thresh = 1e-12 * max(1.0, float(np.abs(snap).max()) if len(snap) else 1.0)
    changed = bool(np.any(np.abs(snap) < thresh))
    if changed:
        snap = np.where(np.abs(snap) < thresh, 0.0, snap)
        ev2 = ctx.evaluate(snap)
        if ctx.violation(ev2) <= best[0]:
            ev = ev2
    return _proposal(ctx, ev)


def _proposal(ctx, ev):
    xval = ev["x"]
    flow = []
    for k in ctx.owned:
        row = [0.0] * len(ctx.paths[k])
        for p in ctx.avail[k]:
            j = ctx.slot_of.get((k, p))
            if j is not None and xval[j] != 0.0:
                row[p] = float(xval[j])
        flow.append(row)
    L = ev["L"]
    potential = [float(ev["lam"][k]) for k in ctx.owned]
    return {
        "status": "optimal",
        "flow": flow,
        "edge_load": [float(v) for v in L],
        "potential": potential,
    }
